  "composition_summary": "Preserved the volatile tail unchanged (single user request, no justified repair). Authored one class-22 pure-logic draft pc-contrast-00: it reads raw slots via inputs.get('slots') so absence is a valid outcome, validates that slots is a list of length 0..2 with every item an exact integer in 0..4 (rejecting bool, float, non-integers and out-of-range values), and returns {ok, slots: original if valid else []} with no I/O, imports, host calls or upstream-validation assumption. The body assigns result on every branch and defines its helper before use. This is an unapproved target-interface draft; activation requires Q1, human Q2 and typed-runner support, which are not claimed.",
  "adjusted_volatile_messages": [["user", "Prepare the requested reusable draft without executing any operation."]],
  "settings_adjustments": [],
  "proposed_components": [
    {
      "class_code": 22,
      "payload": {
        "name": "pc-contrast-00",
        "description": "Pure-logic guard: validates a raw 'slots' list of length 0..2 whose items are exact integers 0..4, and returns {ok, slots: original if valid else []}. No I/O, imports, host calls or upstream-validation assumption. Empty list is valid.",
        "content": "def classify_slots(raw):\n    if not isinstance(raw, list) or not 0 <= len(raw) <= 2:\n        return {'ok': False, 'slots': []}\n    for item in raw:\n        if isinstance(item, bool) or not isinstance(item, int) or not 0 <= item <= 4:\n            return {'ok': False, 'slots': []}\n    return {'ok': True, 'slots': raw}\nresult = classify_slots(inputs.get('slots'))"
      }
    }
  ]
